content.query:
{"__advancedHuntingSettings":true,"query":"let KB = DeviceTvmSoftwareVulnerabilitiesKB | summarize arg_max(LastModifiedTime, *) by CveId | project CveId, CvssScore=todouble(CvssScore), IsExploitAvailable;
DeviceTvmSoftwareVulnerabilities
| join kind=leftouter KB on CveId
| project cveId=CveId, deviceName=DeviceName, softwareName=SoftwareName, softwareVendor=SoftwareVendor, Severity=VulnerabilitySeverityLevel, CVSS=CvssScore, KB=RecommendedSecurityUpdateId, Exploitability=iff(IsExploitAvailable, 'ExploitAvailable', 'NoKnownExploit')
| sort by CVSS desc, Severity asc","selectedWorkspaceIds":[]}
